def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def countBstSubtrees(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    ok = [True] * n
    lo = list(vals)
    hi = list(vals)
    count = 0
    for k in range(n - 1, -1, -1):
        v = vals[k]
        a, b = left[k], right[k]
        if a != -1:
            if ok[a] and hi[a] < v:
                lo[k] = lo[a]
            else:
                ok[k] = False
        if b != -1:
            if ok[b] and lo[b] > v:
                hi[k] = hi[b]
            else:
                ok[k] = False
        if ok[k]:
            count += 1
    return count
